// The assistant's one job: keep a buffer of sendable leads, and never let the
// enrichment backlog sit. Everything else it reports and leaves alone.
const TARGET_DAYS = Number($env.BUFFER_DAYS || 7);
const CAP = Number($env.DAILY_SEND_CAP || 80);
const MIN_CONFIDENCE = Number($env.MIN_CONFIDENCE || 70);
const ENRICH_BATCH = Number($env.ENRICH_BATCH || 25);

const leads = $input.all().map((i) => i.json);
const target = TARGET_DAYS * CAP;

const sendable = leads.filter((l) =>
  l.email &&
  Number(l.confidence || 0) >= MIN_CONFIDENCE &&
  ['new', 'researched', 'enriched'].indexOf(String(l.stage || '').trim()) !== -1
);

// Rows we already have a name and a domain for, but no usable address yet.
const backlog = leads.filter((l) =>
  !l.email &&
  l.domain &&
  (l.first_name || l.last_name) &&
  String(l.stage || '') !== 'suppressed' &&
  String(l.enrich_attempts || '0') < '3'
);

// Rows a human should look at rather than a workflow.
const broken = leads.filter((l) => l.email && !String(l.email).includes('@'));

const deficit = Math.max(0, target - sendable.length);

return [{ json: {
  sendable: sendable.length,
  target: target,
  deficit: deficit,
  days_of_runway: CAP > 0 ? Math.floor(sendable.length / CAP) : 0,
  backlog_total: backlog.length,
  backlog_batch: backlog.slice(0, ENRICH_BATCH),
  broken_rows: broken.length,
  build_needed: deficit > 0 && backlog.length < deficit,
  hour: new Date().toISOString().slice(11, 16)
}}];

// Write results straight back, and count the attempt whether it worked or not -
// three failed attempts and the row stops being retried forever.
const attempted = $('one item per backlog row').all();
const now = new Date().toISOString();
const out = [];
let found = 0;

for (let i = 0; i < $input.all().length; i++) {
  const res = $input.all()[i].json || {};
  const original = (attempted[i] || { json: {} }).json;
  const email = String(res.email || '');
  if (email) found++;

  out.push({ json: {
    lead_id: original.lead_id,
    email: email,
    email_status: res.email_status || 'unknown',
    email_source: res.email_source || '',
    confidence: res.confidence || 0,
    stage: email ? 'enriched' : String(original.stage || 'new'),
    enrich_attempts: Number(original.enrich_attempts || 0) + 1,
    updated_at: now,
    _found: found
  }});
}

return out;

// Hourly workflows that always post get muted. This one speaks when it did something
// or when it needs a human, and is silent otherwise.
const m = $('measure the buffer').first().json;

// The enrichment branch may not have run at all this hour. Referencing a node that
// did not execute throws, so ask for it defensively rather than assuming.
let enriched = [];
try { enriched = $('collect enrichment results').all(); } catch (e) { enriched = []; }
const found = enriched.length ? Number(enriched[enriched.length - 1].json._found || 0) : 0;

const didWork = enriched.length > 0;
const needsHuman = m.build_needed || m.broken_rows > 0 || m.days_of_runway < Number($env.MIN_RUNWAY_DAYS || 3);

if (!didWork && !needsHuman) return [];

const lines = [':gear: *Lead desk ' + m.hour + '* - runway ' + m.days_of_runway + ' days (' + m.sendable + '/' + m.target + ' sendable)'];

if (didWork) lines.push('Enriched ' + enriched.length + ' backlog rows, found ' + found + ' addresses. ' + Math.max(0, m.backlog_total - enriched.length) + ' still queued.');
if (m.build_needed && $env.LIST_BUILD_WEBHOOK_URL) lines.push(':inbox_tray: Buffer short by ' + m.deficit + ' - list build triggered.');
if (m.build_needed && !$env.LIST_BUILD_WEBHOOK_URL) lines.push(':inbox_tray: *Buffer short by ' + m.deficit + ' leads.* No build webhook configured - someone needs to run template 08.');
if (m.broken_rows) lines.push(':wrench: ' + m.broken_rows + ' rows have a malformed email. A human should look.');

return [{ json: { text: lines.join('\n') } }];
